 static Object state(Object result,String error){List ns=new ArrayList(),ps=new ArrayList(),ss=new ArrayList(),ds=new ArrayList();IdentityHashMap<Object,Integer>refs=new IdentityHashMap<>();for(NPC n:nodes){List c=null;if(n.children!=null){c=new ArrayList();for(NPC child:n.children)c.add(child==null?null:child.slot);}ns.add(Arrays.asList(n.id,n.originalId,n.index,n.size,coord(n.location),n.direction==null?null:n.direction.ordinal(),n.active,n.definition==null?null:n.definition.id,n.props==null?null:n.props.slot,n.skills==null?null:n.skills.slot,n.aggressive,n.walkRadius,n.forceTalk,c,n.children==null?null:refs.computeIfAbsent(n.children,k->refs.size())));}for(NPC.Props p:properties)ps.add(Arrays.asList(p.combatLevel,p.attackSpeed,coord(p.spawn),ints(p.bonuses),animation(p.attack),animation(p.defence),animation(p.death),animation(p.magic),animation(p.range),graphics(p.deathGfx),p.bonuses==null?null:refs.computeIfAbsent(p.bonuses,k->refs.size())));for(core.game.node.entity.skill.Skills s:skills)ss.add(Arrays.asList(ints(s.statics),ints(s.currents)));List<Integer>ids=new ArrayList<>(defs.keySet());Collections.sort(ids);for(int id:ids){NPCDefinition d=defs.get(id);List gs=new ArrayList();for(Graphics g:d.combatGraphics)gs.add(graphics(g));ds.add(Arrays.asList(id,gs));}Map out=new TreeMap();out.put("nodes",ns);out.put("props",ps);out.put("skills",ss);out.put("graphics",ds);out.put("repository",new ArrayList<>(repository));out.put("renderable",new ArrayList<>(renderable));out.put("nextIndex",nextIndex);out.put("result",result);out.put("error",error);out.put("events",new ArrayList<>(events));return out;}
 public static void main(String[]args)throws Exception{try(BufferedReader r=new BufferedReader(new InputStreamReader(System.in,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){input=(Map)new JSONParser().parse(line);recording=false;nodes=new ArrayList<>();properties=new ArrayList<>();skills=new ArrayList<>();defs=new HashMap<>();hp=new HashMap<>();repository=new ArrayList<>();renderable=new ArrayList<>();calls=new HashMap<>();events=new ArrayList<>();nextIndex=1;for(Object d:(List)input.getOrDefault("defs",Collections.emptyList()))setDef((Map)d);new NPC(0,Location.create(3207,3216,0));new AbstractNPC(1,Location.create(3210,3216,0));new content.global.skill.summoning.familiar.Familiar(2,Location.create(3207,3216,0));for(Object x:(List)input.getOrDefault("nodes",Collections.emptyList())){Map m=(Map)x;setNode(nodes.get(v(m,"node",0)),m);}if(input.containsKey("hp"))hp.put(2,convert(input.get("hp")));recording=true;List out=new ArrayList();for(Object a:(List)input.get("actions")){events.clear();Object result=null;String error=null;try{result=act((Map)a);}catch(Throwable e){error=e instanceof NullPointerException?"Null":e instanceof IndexOutOfBoundsException?"Index":e instanceof ClassCastException?"Type":e instanceof Failure?"Binding":e.getClass().getSimpleName();}out.add(state(result,error));}input.put("expected",out);System.out.println(JSONValue.toJSONString(input));}}}
